#!/usr/bin/env bash
set -eo pipefail
readonly SEQUENCE=195
readonly OUTPUT_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_coldstart_stress_development_20260924_v1"
readonly SOURCE_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_per_basin_21_development_20260908_v3_aligned_rematch_20260916/workspace"
readonly RUNS_ROOT="/data1/home/sunyiq/kalmannet_daily_camels_per_basin_21_development_20260908_v3_aligned_rematch_20260916/runs"
readonly PYTHON_BIN="/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python"
readonly JOB_NAME="kdpp_cold_s0"
readonly BUNDLE_SHA="62fff26e932fd10e54230608973ff138221e870b4e53a101306ed1aa56772aa9"
readonly PAYLOAD=''
echo "COLDSTART_STRESS_SUBMIT_V1"
echo "sequence=195"
echo "timestamp_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
echo "host=$(hostname)"
if [[ -e "$OUTPUT_ROOT" ]]; then echo "REFUSING: output root already exists" >&2; exit 20; fi
if [[ ! -d "$SOURCE_ROOT" || ! -d "$RUNS_ROOT" || ! -x "$PYTHON_BIN" ]]; then echo "REFUSING: frozen source, runs, or Python absent" >&2; exit 21; fi
own_queue=$(squeue -u "$USER" -h -o '%i|%j|%T|%P|%R')
echo "OWN_QUEUE_BEGIN"
printf '%s\n' "$own_queue"
echo "OWN_QUEUE_END"
if printf '%s\n' "$own_queue" | grep -Eq '(^|[|,])hcpu48([|,]|$)'; then echo "REFUSING: user already has a hcpu48 job" >&2; exit 22; fi
if printf '%s\n' "$own_queue" | grep -Fq "|$JOB_NAME|"; then echo "REFUSING: unique job name already exists" >&2; exit 23; fi
idle_nodes=$(sinfo -h -p hcpu48 -t idle -o '%D' | awk '{sum += $1} END {print sum + 0}')
echo "hcpu48_idle_nodes=$idle_nodes"
if [[ "$idle_nodes" -lt 1 ]]; then echo "REFUSING: no idle hcpu48 node" >&2; exit 24; fi
partition_rules=$(scontrol show partition hcpu48)
if ! printf '%s\n' "$partition_rules" | grep -Fq 'OverSubscribe=EXCLUSIVE'; then echo "REFUSING: CPU allocation rule changed" >&2; exit 25; fi
payload_sha=$(printf '%s' "$PAYLOAD" | base64 --decode | sha256sum | awk '{print $1}')
if [[ "$payload_sha" != "$BUNDLE_SHA" ]]; then echo "REFUSING: embedded payload digest differs" >&2; exit 26; fi
mkdir "$OUTPUT_ROOT"
mkdir -p "$OUTPUT_ROOT/payload" "$OUTPUT_ROOT/logs" "$OUTPUT_ROOT/tmp"
printf '%s' "$PAYLOAD" | base64 --decode | tar -xz -C "$OUTPUT_ROOT/payload"
printf '%s  %s\n' '7ba8a399ec6a39a16a41bc1d1c15cdfc2858168a5804f96cc15543dcc8d48d13' "$OUTPUT_ROOT/payload/bundle_manifest.json" | sha256sum --check --strict
printf '%s  %s\n' \
  '5011308eaffac177cde0fcb9e6cefc10520ab273a7193bba3d18e78b87e3aa52' "$OUTPUT_ROOT/payload/run_coldstart_stress.py" \
  'ba209a4136615a838381cdc7d3448f4ee7e8510beb0b58a70690ed86528e4303' "$OUTPUT_ROOT/payload/authorization_coldstart.json" \
  '6675dc89e6732a801a43a527bfb1848e15c25d7bb62a3332d6beb817a911569e' "$OUTPUT_ROOT/payload/submit.slurm" \
  '030e8cce6c4818e35fba9dc22fb39e93fb118996ea1e77706f50c2367cd49ffe' "$OUTPUT_ROOT/payload/source_manifest.json" \
  '7281fc490e8aff1c05e1a1aea9bf214a66101b9bc80970337ca3e374acc7cb96' "$OUTPUT_ROOT/payload/gate_expected.json" | sha256sum --check --strict
bash -n "$OUTPUT_ROOT/payload/submit.slurm"
chmod 0555 "$OUTPUT_ROOT/payload/submit.slurm"
echo "STAGED_BUNDLE_SHA=$BUNDLE_SHA"
submit_output=$(sbatch "$OUTPUT_ROOT/payload/submit.slurm" 2>&1) || { printf '%s\n' "$submit_output"; exit 30; }
printf '%s\n' "$submit_output"
receipt_lines=$(printf '%s\n' "$submit_output" | grep -E '^Submitted batch job [0-9]+$' || true)
receipt_count=$(printf '%s' "$receipt_lines" | grep -c . || true)
if [[ "$receipt_count" -ne 1 ]]; then echo "NO_SINGLE_CANONICAL_SCHEDULER_RECEIPT count=$receipt_count; check squeue before any action" >&2; exit 31; fi
job_id=$(printf '%s\n' "$receipt_lines" | grep -oE '[0-9]+$')
submitted_at=$(date -u +%Y-%m-%dT%H:%M:%SZ)
printf '{"schema_version":"daily_camels_coldstart_stress_submission_receipt_v1","job_id":"%s","job_name":"%s","partition":"hcpu48","submitted_at_utc":"%s","retry_allowed":false,"bundle_sha256":"%s"}\n' "$job_id" "$JOB_NAME" "$submitted_at" "$BUNDLE_SHA" > "$OUTPUT_ROOT/submission_receipt.json"
chmod 0444 "$OUTPUT_ROOT/submission_receipt.json"
echo "job_id=$job_id"
echo "output_root=$OUTPUT_ROOT"
